// Grid Walker

const STIFFNESS = 0.1;
const DAMPING = 0.9;
const MAX_VELOCITY = 5.0;

const COLS = 10; 
const ROWS = 25;
const SPACING = 35; 

const FLOOR_Y = 160;
const SPEED = 0.05; 

const points = [];

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  perspective(PI / 3, width / height, 0.1, 10000);

  for (let i = 0; i < COLS; i++) {
    points[i] = [];
    for (let j = 0; j < ROWS; j++) {
      points[i][j] = {
        pos: createVector((i - COLS / 2) * SPACING, 0, (j - ROWS / 2) * SPACING),
        vel: createVector(0, 0, 0),
        fixed: (i === 0 || i === COLS - 1)
      };
    }
  }
}

function draw() {
  background(255); 
  rotateY(PI/2); 
  orbitControl();

  drawFloor(FLOOR_Y);

  updateBoundaries();
  updatePoints();

  fill(255);
  stroke(0);
  strokeWeight(2);

  for (let i = 0; i < COLS - 1; i++) {
    beginShape(QUAD_STRIP);
    for (let j = 0; j < ROWS; j++) {
      const p1 = points[i][j];
      const p2 = points[i + 1][j];
      vertex(p1.pos.x, p1.pos.y, p1.pos.z);
      vertex(p2.pos.x, p2.pos.y, p2.pos.z);
    }
    endShape();
  }
}


function drawFloor(floorY) {
  stroke(0);
  strokeWeight(2);
  const floorSize = 2000;
  const gridSize = 200;

  const offset = (frameCount * SPEED * SPACING * 4) % gridSize;
    for (let i = -floorSize; i <= floorSize; i += gridSize) {
    line(i, floorY, -floorSize, i, floorY, floorSize);

    const z = i - offset;
    if (z >= -floorSize && z <= floorSize) {
      line(-floorSize, floorY, z, floorSize, floorY, z);
    }
  }
}

function updateBoundaries() {
  for (const i of [0, COLS - 1]) {
    for (let j = 0; j < ROWS; j++) {
      const p = points[i][j];
      const v = map(j, 0, ROWS - 1, 0, 1);
      const angle = v * PI * 2 + frameCount * SPEED;
      const radius = FLOOR_Y;
      const offset = (i === COLS - 1) ? PI : 0;

      p.pos.y = sin(angle + offset) * radius;
      p.pos.z = (j - ROWS / 2) * SPACING + cos(angle + offset) * (radius * 0.5);
    }
  }
}

function updatePoints() {
  const substeps = 3;
  for (let n = 0; n < substeps; n++) {
    for (let i = 0; i < COLS; i++) {
      for (let j = 0; j < ROWS; j++) {
        const p = points[i][j];
        if (p.fixed) continue;
        let sum = createVector(0, 0, 0);
        let count = 0;
        for (const [ni, nj] of [[i - 1, j], [i + 1, j], [i, j - 1], [i, j + 1]]) {
          if (points[ni] && points[ni][nj]) {
            sum.add(points[ni][nj].pos);
            count++;
          }
        }
        if (count > 0) {
          let force = p5.Vector.sub(p5.Vector.div(sum, count), p.pos).mult(STIFFNESS);
          p.vel.add(force);
          p.vel.limit(MAX_VELOCITY);
        }
      }
    }
    for (let i = 0; i < COLS; i++) {
      for (let j = 0; j < ROWS; j++) {
        const p = points[i][j];
        if (p.fixed) continue;
        p.pos.add(p.vel);
        p.vel.mult(DAMPING);
      }
    }
  }
}

// 1. 免疫 DOM 元素建立導致的看門狗攔截
if (typeof createP === 'undefined') { window.createP = function() { return { position: function(){}, style: function(){} }; }; }
if (typeof createDiv === 'undefined') { window.createDiv = function() { return { position: function(){}, style: function(){} }; }; }

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || (path.startsWith('http') === false && path.startsWith('data:') === false)) {
            // 當發現是相對路徑或丟失的外部圖片資產時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (this.width === 0 || this.height === 0) {
            return createGraphics(10, 10);
        }
        return window._origGet.apply(this, args);
    };
}
